    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    expect(await ui.addAlias(pg_uma, p_ada, "Addie")).toBe(true);
    expect(await ui.importPeople(pg_uma, "Ben,B\n Cam ,C,3,cam@x")).toMatchObject({"added": 2});
    const p_ben = await ui.personId(pg_uma, "Ben");
    const p_cam = await ui.personId(pg_uma, "Cam");
    expect(await ui.importPeople(pg_uma, "Dot,A\nada,B")).toBeNull();
    expect(await ui.importPeople(pg_uma, "Dot,A\naddie,B")).toBeNull();
    expect(await ui.importPeople(pg_uma, "Dot,A\nEve,B,x")).toBeNull();
    expect(await ui.importPeople(pg_uma, "Dot,A,,CAM@X")).toBeNull();
    expect(await ui.importPeople(pg_uma, "Dot,A\ndot,B")).toBeNull();
    expect(await ui.importPeople(pg_uma, "Dot,D")).toBeNull();
