        LocalDate today = sheets.load(sheetId, user).getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (person.getVersion() != version) {
            throw changedSince();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
                || people.findBySheetIdAndAliasIgnoreCase(sheetId, trimmed).isPresent()) {
            throw nameInUse();
        }
        if (throughForm) {
            Set<String> used = usedInTree(sheetId);
            if (used.contains(lower(trimmed)) || person.getAliases().stream().anyMatch(a -> used.contains(lower(a)))) {
                throw nameInUse();
            }
        }
        String reach = contactOf(contact);
        if (reach != null && people.existsBySheetIdAndContactAndIdNot(sheetId, reach, id)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.of(sheetId);
        person.setName(trimmed);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade);
        }
        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
        person.setTerms(terms);
        boolean contactChanged = !Objects.equals(person.getContact(), reach);
        person.setContact(reach);
        Person edited = save(person);
        audit.recordChangeOnCommit(sheetId, user, entry("PERSON_EDITED", user, edited, edited.gradeOn(today))
                + (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
                + (contactChanged ? " contact=" + (reach != null ? reach : "") : ""));
        rollup.recordChanges(sheetId, user, before);
        return edited;
    }

    /** Retire a person from a date; a missing date takes the sheet's today. They count as retired at once; the live
     *  totals move with it once the sheet's today reaches the date. */
    @Transactional
    public Person retire(String sheetId, String user, long id, LocalDate from) {
        LocalDate today = sheets.load(sheetId, user).getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Rollup.Figures before = rollup.of(sheetId);
        person.setRetiredFrom(from != null ? from : today);
        Person retired = save(person);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + retired.getName() + " from=" + retired.getRetiredFrom());
        rollup.recordChanges(sheetId, user, before);
        return retired;
    }

    /** Put the person on hold from {@code from} (null: the sheet's today) to {@code to} (null: no end), alongside
     *  any holds they have already; the live totals move with it. A to-date before the from-date is refused. */
    @Transactional
    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
        LocalDate today = sheets.load(sheetId, user).getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        LocalDate start = from != null ? from : today;
        if (to != null && to.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
        }
        Rollup.Figures before = rollup.of(sheetId);
        person.addHold(new Hold(start, to));
        Person saved = save(person);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + start);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** Give the person an alias, stored trimmed: refused when blank, or when it is, without regard to case, any
     *  name or alias on the sheet or on another sheet of its tree. */
    @Transactional
    public Person addAlias(String sheetId, String user, long id, String alias) {
        sheets.load(sheetId, user);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        String trimmed = alias == null ? "" : alias.trim();
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An alias cannot be blank");
        }
        if (people.findBySheetIdAndNameOrAliasIgnoreCase(sheetId, trimmed).isPresent()
                || usedInTree(sheetId).contains(lower(trimmed))) {
            throw nameInUse();
        }
        person.addAlias(trimmed);
        Person saved = save(person);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " alias=" + trimmed);
        return saved;
    }

    private static String entry(String event, String user, Person person, String grade) {
        return event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + grade;
    }

    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException raced) {
            // Another user took the same name at the same moment: theirs stands.
            throw nameInUse();
        } catch (ObjectOptimisticLockingFailureException raced) {
            // Another user saved the same person at the same moment: theirs stands.
            throw changedSince();
        }
    }

    private static ResponseStatusException changedSince() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened");
    }

    /** A contact as stored: trimmed and lower-cased; null when blank or not given. */
    private static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) {
            return null;
        }
        return contact.trim().toLowerCase(Locale.ROOT);
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
    }
}
package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The paste box: a DRAFT claim per pasted line, for a person already on the sheet. */
@Service
public class PasteService {

    /** An amount as the claim form takes it: up to twelve digits and two decimals, negative for a correction. */
    private static final java.util.regex.Pattern AMOUNT = java.util.regex.Pattern.compile("-?\\d{1,12}(\\.\\d{1,2})?");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 1000;

    /** The longest external reference the claim form takes. */
    private static final int REF_MAX = 120;

    private final PersonRepository people;
    private final ClaimService claims;

    public PasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /** A pasted line read into a claim's values. */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
    }

    /**
     * Add a DRAFT claim per line of {@code text} (name,amount,date,note; the note may hold commas, a blank date
     * takes the sheet's entry date while set, else its today, the note may be absent), in order, for the person on the sheet whose name or an alias matches
     * (trimmed, ignoring case). Each line is checked by exactly the claim form's rules; one change: when any line
     * is refused, nothing is added and nothing is recorded. Blank lines are skipped; a paste with no lines is
     * refused. A note ending in {@code " #<reference>"} gives the claim that external reference, which is not part of
     * the note; a reference used on the sheet or on an earlier line, without regard to case, refuses the paste.
     */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (String raw : text.split("\\r?\\n")) {
            if (!raw.isBlank()) {
                Line line = read(sheetId, raw);
                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
                    throw ClaimService.refUsed(line.ref());
                }
                lines.add(line);
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            added.add(claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
                    line.ref()));
        }
        return added;
    }

    private Line read(String sheetId, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 2) {
            throw refused("Each line needs at least a name and an amount");
        }
        String name = fields[0].trim();
        if (name.isEmpty()) {
            throw refused("Each line needs a name");
        }
        Person person = people.findBySheetIdAndNameOrAliasIgnoreCase(sheetId, name)
                .orElseThrow(() -> refused("No one named " + name + " is on this sheet"));
        String amount = fields[1].trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw refused("An amount takes up to two decimals");
        }
        LocalDate date = null;
        String dateText = fields.length > 2 ? fields[2].trim() : "";
        if (!dateText.isEmpty()) {
            try {
                date = LocalDate.parse(dateText);
            } catch (DateTimeParseException e) {
                throw refused("A date is written yyyy-mm-dd");
            }
        }
        String note = fields.length > 3 ? fields[3] : "";
        if (note.length() > NOTE_MAX) {
            throw refused("A note is at most " + NOTE_MAX + " characters");
        }
        String ref = null;
        String trimmed = note.trim();
        int hash = trimmed.lastIndexOf(" #");
        if (hash >= 0 && !trimmed.substring(hash + 2).isBlank()) {
            ref = ClaimService.refOf(trimmed.substring(hash + 2));
            note = trimmed.substring(0, hash);
        }
        if (ref != null && ref.length() > REF_MAX) {
            throw refused("A reference is at most " + REF_MAX + " characters");
        }
        return new Line(person, new BigDecimal(amount), date, note, ref);
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
    }
}
}

/** The result count a button shows once its action is done (how many were added, made, opened).
 *  `was` is what the cell showed before the click. The count is taken once it differs from `was`,
 *  or once the cell was seen cleared and shown again (README: a result is cleared when its button
 *  is pressed again). Two identical results in a row can look the same on screen for the whole
 *  wait: then, with no error showing and a value in the cell, that value is taken rather than
 *  failing a step the app did take. */
async function countAfter(page: Page, cell: Locator, error: Locator, what: string, was: string): Promise<string | null> {
  let cleared = false;
  const done = async () => {
    if ((await cell.count()) === 0) return false;
    const now = await shown(cell);
    if (now === '') { cleared = true; return false; }
    return now !== was || was === '' || cleared;
  };
  try {
    return (await until(page, done, error, what)) ? await shown(cell) : null;
  } catch (e) {
    if (await error.isVisible().catch(() => false)) return null;
    if ((await cell.count()) > 0 && (await shown(cell)) !== '') return shown(cell);
    throw e;
  }
}

// ---- session ---------------------------------------------------------------------------------

// Each sign-in gets its own browser context, so users on one sheet act independently. A context
// is closed once the test that opened it has finished: the test runner leaves them open, and a
// whole suite of open pages, each still running the app, would exhaust the machine.
const opened = new Map<BrowserContext, string>();   // context -> id of the test that opened it

export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
  let owner = '';
  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
  for (const [c, t] of opened) {
    if (t === owner) continue;
    opened.delete(c);
    await c.close().catch(() => { /* already gone */ });
  }
  const context = await browser.newContext();

